import React from 'react';
import ClientesCarrusel from '../components/ClientesCarrusel';
import { Link, useNavigate } from 'react-router-dom';
import '../styles/Inicio.css';

const Inicio = () => {
  const navigate = useNavigate();
  return (
  <div
    className="inicio-container"
    style={{
      backgroundImage: "url('/fondo-naranja.png')",
      backgroundPosition: "center",
      backgroundSize: "cover",
      backgroundRepeat: "no-repeat"
    }}
  >
      <h1 className="inicio-title">PHG Soluciones Contables</h1>
      <p className="inicio-desc">Tu aliado en servicios contables, auditoría y asesoría financiera.</p>
      <nav className="inicio-nav">
        <Link to="/servicios">Servicios</Link>
        <Link to="/sobre-nosotros">Sobre Nosotros</Link>
        <Link to="/contacto">Contacto</Link>
        <Link to="/ubicacion-redes">Ubicación y Redes</Link>
      </nav>
    <img src="/logo.png" alt="PHG Soluciones Contables" className="inicio-logo" />
    {/* Botón 'Regresar' eliminado de Inicio */}
    <ClientesCarrusel />
    </div>
  );
};

export default Inicio;
